C_TEMPLATE_HEADER = "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n"
def c_wrapped(code):
    if "#include" in code or "main(" in code:
        return code
    indented="\n".join("    "+line for line in code.split("\n"))
    return C_TEMPLATE_HEADER + "int main() {\n" + indented + "\n    return 0;\n}\n"

