def deno_missing(mode):
    if mode=="stdin":
        return "failed to start Deno for stdin execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH."
    if mode=="file":
        return "failed to run Deno for file execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH."
    return "failed to run Deno for inline execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH."

