    if lang=="lua":
        try: return run_cmd([exe,"-e",code], capture=capture)
        except OSError as e: spawn_error_generic(e)
    if lang=="php":
        try: return run_cmd([exe,"-r",code], capture=capture)
        except OSError as e: spawn_error_generic(e)
    # snippet file languages
    extmap={"dart":"dart","elixir":"ex","groovy":"groovy","haskell":"hs","julia":"jl","nim":"nim","r":"R","swift":"swift","crystal":"cr","zig":"zig"}
    ext=extmap.get(lang,"txt")
