    if lang=="ruby":
        try: return run_cmd(["ruby",path], capture=capture)
        except OSError as e: spawn_error_generic(e)
    if lang=="typescript":
        return exec_typescript_file(path,capture)
    exe=check_friendly(lang) if lang in FRIENDLY else None
    cmdmap={
      "lua":[exe,path],"php":[exe,path],"dart":[exe,path],"elixir":[exe,path],"groovy":[exe,path],
      "haskell":[exe,path],"julia":[exe,path],"r":[exe,path],"swift":[exe,path],"crystal":[exe,"run",path],"zig":[exe,"run",path],
