    cmd=cmdmap.get(lang,[exe,path] if exe else [lang,path])
    try: return run_cmd(cmd, capture=capture)
    except OSError as e: spawn_error_generic(e)

def execute_code(lang, code, capture=False):
    if lang=="python": return exec_python_code(code,capture)
    if lang=="bash": return exec_bash_code(code,capture)
    if lang=="perl": return exec_perl_code(code,capture)
    if lang=="go": return exec_go_code(code,capture)
    if lang=="c": return exec_c_code(code,capture)
    if lang=="cpp": return exec_cpp_code(code,capture)
    if lang=="rust": return exec_rust_code(code,capture)
    if lang=="java": return exec_java_code(code,capture)
    if lang=="kotlin": return exec_kotlin_code(code,capture)
    if lang=="typescript": return exec_typescript_code(code,capture)
    if lang=="csharp": return exec_csharp_code(code,capture)
