    if lang=="typescript": return exec_typescript_file(path,capture)
    if lang=="csharp": return exec_csharp_file(path,capture)
    return exec_script_file(lang, path, capture)

def execute_stdin(lang, code, capture=False):
    if lang=="python": return exec_python_stdin(code,capture)
    if lang=="bash": return exec_bash_stdin(code,capture)
