class RunError(Exception):
    pass

class ClapExit(Exception):
    def __init__(self, code, text, stream):
        self.code=code; self.text=text; self.stream=stream

def prog_name():
    p = sys.argv[0] if sys.argv else "executable"
    b = os.path.basename(p)
    return b or p or "executable"

def help_text():
    p = prog_name()
    return f"""Universal multi-language runner and REPL

Usage: {p} [OPTIONS] [ARGS]...

Arguments:
  [ARGS]...  Positional arguments (language, code, or file)

Options:
  -V, --version      Print version information and exit
  -l, --lang <LANG>  Explicitly choose the language to execute
  -f, --file <PATH>  Execute code from the provided file path
  -c, --code <CODE>  Execute the provided code snippet
      --no-detect    Disable heuristic language detection
  -h, --help         Print help
"""

def os_error_str(e):
    if isinstance(e, FileNotFoundError):
        return "No such file or directory (os error 2)"
    if isinstance(e, PermissionError):
        return "Permission denied (os error 13)"
    if isinstance(e, IsADirectoryError):
        return "Is a directory (os error 21)"
    if isinstance(e, NotADirectoryError):
        return "Not a directory (os error 20)"
    errno = getattr(e, 'errno', None)
    msg = getattr(e, 'strerror', None) or str(e)
    if errno:
        return f"{msg} (os error {errno})"
    return msg

def parse_language(raw):
    if raw is None:
        return None
    key = raw.strip().lower()
    return ALIASES.get(key)

def parse_language_or_cli_error(raw):
    canon = parse_language(raw)
    if canon is None:
        key = raw.strip().lower()
        raise RunError(f"Unknown language '{key}'. Available languages: {LANG_CSV}")
    return canon

# ---------- clap-like parsing ----------
OPT_DISPLAY = {
 "lang": "--lang <LANG>",
 "file": "--file <PATH>",
 "code": "--code <CODE>",
 "version": "--version",
 "no-detect": "--no-detect",
 "help": "--help",
}
LONG_OPTS = {
 "lang": ("lang", True), "file": ("file", True), "code": ("code", True),
 "version": ("version", False), "no-detect": ("no-detect", False), "help": ("help", False),
}
SHORT_OPTS = {"l":"lang","f":"file","c":"code","V":"version","h":"help"}

def _jaro(s1,s2):
    if s1==s2: return 1.0
    len1,len2=len(s1),len(s2)
    if len1==0 or len2==0: return 0.0
    match_dist=max(len1,len2)//2-1
    if match_dist<0: match_dist=0
    m1=[False]*len1; m2=[False]*len2; matches=0
    for i,ch in enumerate(s1):
        lo=max(0,i-match_dist); hi=min(len2,i+match_dist+1)
        for j in range(lo,hi):
            if not m2[j] and s2[j]==ch:
                m1[i]=True; m2[j]=True; matches+=1; break
    if matches==0: return 0.0
    t=0; k=0
    for i in range(len1):
        if m1[i]:
            while not m2[k]: k+=1
            if s1[i]!=s2[k]: t+=1
            k+=1
    t//=2
    return (matches/len1 + matches/len2 + (matches-t)/matches)/3.0

def _jaro_winkler(s1,s2):
    j=_jaro(s1,s2)
    pref=0
    for a,b in zip(s1,s2):
        if a==b and pref<4: pref+=1
        else: break
    return j + pref*0.1*(1-j)

def suggest_long(unknown_name, full_token):
    # unknown_name without leading --
    cands=["help","version","lang","file","code","no-detect"]
    best=None; bestscore=0.0
    for c in cands:
        scores=[_jaro_winkler(unknown_name,c), _jaro_winkler("--"+unknown_name,"--"+c), _jaro_winkler(full_token,"--"+c)]
        score=max(scores)
        # prefix bonus like clap
        if c.startswith(unknown_name) or unknown_name.startswith(c):
            score=max(score,0.85)
        if unknown_name.lower()==c.lower():
            score=max(score,0.9)
        if score>bestscore:
            bestscore=score; best=c
    if best and bestscore>=0.78:
        return best
    return None

class Cli:
    def __init__(self):
        self.lang=None; self.file=None; self.code=None; self.no_detect=False; self.version=False; self.args=[]
        self.used=[]  # list of canonical keys in order of successful option use (long/short)
    def mark_used(self,key):
        if key not in self.used:
            self.used.append(key)

def clap_error_unknown(token_display, is_long, cli, suggestion=None):
    p=prog_name()
    lines=[f"error: unexpected argument '{token_display}' found", ""]
    if suggestion:
        lines.append(f"  tip: a similar argument exists: '--{suggestion}'")
    lines.append(f"  tip: to pass '{token_display}' as a value, use '-- {token_display}'")
    lines.append("")
    if is_long:
        used_keys=list(cli.used)
        # suggested option is shown in usage even if not used
        if suggestion and suggestion not in used_keys:
            used_keys.append(suggestion)
        if used_keys:
            usage_parts=" ".join(OPT_DISPLAY[k] for k in used_keys)
            lines.append(f"Usage: {p} {usage_parts} [ARGS]...")
        else:
            lines.append(f"Usage: {p} [OPTIONS] [ARGS]...")
    else:
        lines.append(f"Usage: {p} [OPTIONS] [ARGS]...")
    lines.append("")
    lines.append("For more information, try '--help'.")
    raise ClapExit(2, "\n".join(lines)+"\n", sys.stderr)

def clap_error_missing(key):
    disp=OPT_DISPLAY[key]
    txt=f"error: a value is required for '{disp}' but none was supplied\n\nFor more information, try '--help'.\n"
    raise ClapExit(2, txt, sys.stderr)

def clap_error_duplicate(key):
    disp=OPT_DISPLAY[key]
    p=prog_name()
    txt=f"error: the argument '{disp}' cannot be used multiple times\n\nUsage: {p} [OPTIONS] [ARGS]...\n\nFor more information, try '--help'.\n"
    raise ClapExit(2, txt, sys.stderr)

def clap_error_unexpected_value(key, value):
    p=prog_name()
    disp_simple=f"--{key}"
    # weird alternation case mirrored roughly: if a flag was used before
    txt=f"error: unexpected value '{value}' for '{disp_simple}' found; no more were expected\n\nUsage: {p} {disp_simple} [ARGS]...\n\nFor more information, try '--help'.\n"
    raise ClapExit(2, txt, sys.stderr)

def parse_cli(argv):
    cli=Cli()
    i=0
    n=len(argv)
    positional_only=False
    # helper to fetch value for a pending option starting at i (value token is argv[i] candidate)
    def fetch_value(key, idx):
        # idx points to next token to examine; returns (value, next_idx) or raises
        if idx>=n:
            clap_error_missing(key)
        tok=argv[idx]
        if tok=="":
            clap_error_missing(key)
        if tok=="--":
            clap_error_missing(key)
        if tok=="-" or not tok.startswith("-"):
            return tok, idx+1
        # tok looks like a flag
        if tok.startswith("--"):
            name_eq=tok[2:]
            if "=" in name_eq:
                name=name_eq.split("=",1)[0]
            else:
                name=name_eq
            if name in LONG_OPTS:
                clap_error_missing(key)
            else:
                # unknown long
                sugg=suggest_long(name, "--"+name)
                clap_error_unknown("--"+name, True, cli, sugg)
        else:
            # short cluster
            if len(tok)>=2:
                first=tok[1]
                if first in SHORT_OPTS:
                    clap_error_missing(key)
                else:
                    clap_error_unknown("-"+first, False, cli, None)
            clap_error_missing(key)
    seen_value_opts=set()
    while i<n:
        tok=argv[i]
        if positional_only:
            cli.args.append(tok); i+=1; continue
        if cli.args:
            # after first positional, everything literal (allow_hyphen)
            cli.args.append(tok); i+=1; continue
        if tok=="--":
            positional_only=True; i+=1; continue
        if tok.startswith("--") and len(tok)>2:
            body=tok[2:]
            if "=" in body:
                name,value=body.split("=",1)
                has_eq=True
            else:
                name,value,has_eq=body,None,False
            if name not in LONG_OPTS:
                sugg=suggest_long(name, "--"+name)
                clap_error_unknown("--"+name, True, cli, sugg)
            key, takes = LONG_OPTS[name]
            if not takes:
                if has_eq:
                    # duplicate-ish special: clap shows value error
                    clap_error_unexpected_value(key, value)
                if key=="help":
                    raise ClapExit(0, help_text(), sys.stdout)
                # duplicate flag check
                if key=="version":
                    if cli.version:
                        clap_error_duplicate("version")
                    cli.version=True; cli.mark_used("version")
                elif key=="no-detect":
                    if cli.no_detect:
                        clap_error_duplicate("no-detect")
                    cli.no_detect=True; cli.mark_used("no-detect")
                i+=1; continue
            else:
                # takes value
                if has_eq:
                    if key in seen_value_opts:
                        clap_error_duplicate(key)
                    if value=="":
                        clap_error_missing(key)
                    val=value; i+=1
                else:
                    val,i_next=fetch_value(key, i+1)
                    if key in seen_value_opts:
                        clap_error_duplicate(key)
                    val=val; i=i_next
                seen_value_opts.add(key); cli.mark_used(key)
                setattr(cli, key, val)
                continue
        elif tok.startswith("-") and tok!="-" and len(tok)>1:
            # short cluster
            j=1
            consumed_next=False
            while j < len(tok):
                ch=tok[j]
                if ch not in SHORT_OPTS:
                    clap_error_unknown("-"+ch, False, cli, None)
                key=SHORT_OPTS[ch]
                if key=="help":
                    raise ClapExit(0, help_text(), sys.stdout)
                if key=="version":
                    if cli.version:
                        clap_error_duplicate("version")
                    cli.version=True; cli.mark_used("version"); j+=1; continue
                # takes value
                rest=tok[j+1:]
                if rest.startswith("="):
                    if key in seen_value_opts:
                        clap_error_duplicate(key)
                    rest_val=rest[1:]
                    if rest_val=="":
                        clap_error_missing(key)
                    val=rest_val; j=len(tok)
                elif rest:
                    if key in seen_value_opts:
                        clap_error_duplicate(key)
                    val=rest; j=len(tok)
                else:
                    val,i_next=fetch_value(key, i+1)
                    if key in seen_value_opts:
                        clap_error_duplicate(key)
                    consumed_next=True; j=len(tok)
                    i=i_next-1  # will be +1 below
                seen_value_opts.add(key); cli.mark_used(key)
                setattr(cli, key, val)
            i+=1; continue
        else:
            # positional (including "-", "", plain)
            cli.args.append(tok); i+=1; continue
    # trailing pending handled in fetch
    return cli

# ---------- temp dirs ----------
def make_temp_dir(prefix):
    # prefix like "run-c" or ".tmp" ; create in /tmp with 6-char suffix
    base="/tmp"
    for _ in range(100):
        suffix="".join(random.choice(string.ascii_letters+string.digits) for _ in range(6))
        path=os.path.join(base, prefix+suffix)
        try:
            os.makedirs(path)
            return path
        except FileExistsError:
            continue
    return tempfile.mkdtemp(prefix=prefix)

import tempfile as _tf
class TempDirCtx:
    def __init__(self,prefix):
        self.prefix=prefix; self.path=None
    def __enter__(self):
        self.path=make_temp_dir(self.prefix); return self.path
    def __exit__(self,exc_type,exc,tb):
        if self.path:
            import shutil as _sh
            _sh.rmtree(self.path, ignore_errors=True)
        return False

def which(name):
    return shutil.which(name)

def resolve_python():
    return which("python3") or which("python")

def status_exit_code(rc):
    if rc is None: return 0
    if rc<0: return 0
    return rc

def run_cmd(cmd, cwd=None, stdin_data=None, capture=False):
    """Returns exit code (non-capture: inherits stdio unless stdin_data). Raises OSError on spawn failure."""
    try:
        if capture:
            p=subprocess.run(cmd, cwd=cwd, input=stdin_data, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            return status_exit_code(p.returncode), p.stdout, p.stderr
        else:
            if stdin_data is not None:
                p=subprocess.run(cmd, cwd=cwd, input=stdin_data)
            else:
                p=subprocess.run(cmd, cwd=cwd)
            return status_exit_code(p.returncode), b"", b""
    except OSError as e:
        raise

def spawn_error_generic(e):
    raise RunError(os_error_str(e))

def check_friendly(lang):
    if lang in FRIENDLY:
        exe,msg=FRIENDLY[lang]
        if not which(exe):
            raise RunError(msg)
        return which(exe)
    return None

# ---------------- language executors ----------------
def exec_python_code(code,capture=False):
    exe=resolve_python() or "python3"
    try:
        return run_cmd([exe,"-c",code], capture=capture)
    except OSError as e:
        spawn_error_generic(e)

def exec_python_file(path,capture=False):
    exe=resolve_python() or "python3"
    try:
        return run_cmd([exe,path], capture=capture)
    except OSError as e:
        spawn_error_generic(e)

def exec_python_stdin(code,capture=False):
    exe=resolve_python() or "python3"
    data=code.encode() if isinstance(code,str) else code
    try:
        if capture:
            return run_cmd([exe,"-"], stdin_data=data, capture=True)
        else:
            return run_cmd([exe,"-"], stdin_data=data, capture=False)
    except OSError as e:
        raise RunError(f"failed to start python3 for stdin execution\n\nCaused by:\n    {os_error_str(e)}")

def bash_exe():
    return which("bash") or ("/bin/bash" if os.path.exists("/bin/bash") else "bash")

def exec_bash_code(code,capture=False):
    exe=bash_exe()
    try:
        return run_cmd([exe,"-c",code], capture=capture)
    except OSError as e:
        spawn_error_generic(e)
def exec_bash_file(path,capture=False):
    exe=bash_exe()
    try:
        return run_cmd([exe,path], capture=capture)
