def exec_perl_code(code,capture=False):
    exe=check_friendly("perl")
    with TempDirCtx("run-perl") as td:
        snippet=os.path.join(td,"snippet.pl")
        with open(snippet,"w") as f:
            f.write(code)
            if not code.endswith("\n"): f.write("\n")
        try:
            return run_cmd([exe,snippet], capture=capture)
        except OSError as e:
            spawn_error_generic(e)

def exec_perl_file(path,capture=False):
    exe=check_friendly("perl")
    parent=os.path.dirname(path)
    # perl is invoked with given path but cwd is parent (original bug)
    try:
        return run_cmd([exe,path], cwd=parent, capture=capture)
    except OSError as e:
        raise RunError(f"failed to execute {exe} with script {path}\n\nCaused by:\n    {os_error_str(e)}")

def exec_go_code(code,capture=False):
    exe=check_friendly("go")
    with TempDirCtx("run-go") as td:
        main=os.path.join(td,"main.go")
        with open(main,"w") as f: f.write(code)
        try:
            return run_cmd([exe,"run","main.go"], cwd=td, capture=capture)
        except OSError as e:
            spawn_error_generic(e)

def exec_go_file(path,capture=False):
    exe=check_friendly("go")
    parent=os.path.dirname(path)
    base=os.path.basename(path)
    try:
        return run_cmd([exe,"run",base], cwd=parent, capture=capture)
    except OSError as e:
        raise RunError(f"failed to invoke {exe} to run {path}\n\nCaused by:\n    {os_error_str(e)}")

C_TEMPLATE_HEADER = "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n"
def c_wrapped(code):
    if "#include" in code or "main(" in code:
        return code
    indented="\n".join("    "+line for line in code.split("\n"))
    return C_TEMPLATE_HEADER + "int main() {\n" + indented + "\n    return 0;\n}\n"

def find_c_compiler():
    for cand in ["cc","clang","gcc"]:
        p=which(cand)
        if p: return p
    return None
def find_cpp_compiler():
    for cand in ["c++","clang++","g++"]:
        p=which(cand)
        if p: return p
    return None

def compile_and_run(compiler, src_path, binary_path, extra_args, capture):
    try:
        rc,out,err=run_cmd([compiler, src_path, "-o", binary_path]+extra_args, capture=capture)
    except OSError as e:
        spawn_error_generic(e)
    if rc!=0:
        return rc,out,err
    try:
        return run_cmd([binary_path], capture=capture)
    except OSError as e:
        spawn_error_generic(e)

def exec_c_code(code,capture=False):
    comp=find_c_compiler()
    if not comp:
        raise RunError("C support requires a C compiler such as `cc`, `clang`, or `gcc`. Install one and ensure it is on your PATH.")
    with TempDirCtx("run-c") as td:
        src=os.path.join(td,"main.c"); binary=os.path.join(td,"run_c_binary")
        with open(src,"w") as f: f.write(c_wrapped(code))
        return compile_and_run(comp, src, binary, ["-std=c11","-lm"], capture)

def exec_c_file(path,capture=False):
    with TempDirCtx("run-c") as td:
        dest=os.path.join(td,"main.c")
        try:
            shutil.copyfile(path, dest)
        except OSError as e:
            raise RunError(f"failed to copy C source from {path} to {dest}\n\nCaused by:\n    {os_error_str(e)}")
        comp=find_c_compiler()
        if not comp:
            raise RunError("C support requires a C compiler such as `cc`, `clang`, or `gcc`. Install one and ensure it is on your PATH.")
        binary=os.path.join(td,"run_c_binary")
        return compile_and_run(comp, dest, binary, ["-std=c11","-lm"], capture)

def exec_cpp_code(code,capture=False):
    comp=find_cpp_compiler()
    if not comp:
        raise RunError("C++ support requires a C++ compiler such as `c++`, `clang++`, or `g++`. Install one and ensure it is on your PATH.")
    with TempDirCtx("run-cpp") as td:
        src=os.path.join(td,"main.cpp"); binary=os.path.join(td,"run_cpp_binary")
        with open(src,"w") as f: f.write(code)
        return compile_and_run(comp, src, binary, ["-std=c++17","-lm"], capture)

