def exec_java_code(code,capture=False):
    check_friendly("java")
    with TempDirCtx("run-java") as td:
        src=os.path.join(td,"Main.java")
        if "class" in code:
            content=code
        else:
            indented="\n".join("        "+l for l in code.split("\n"))
            content="public class Main {\n    public static void main(String[] args) {\n"+indented+"\n    }\n}\n"
        with open(src,"w") as f: f.write(content)
        javac=which("javac"); java=which("java") or "java"
        try:
            rc,out,err=run_cmd([javac, src], cwd=td, capture=capture)
        except OSError as e: spawn_error_generic(e)
        if rc!=0: return rc,out,err
        try: return run_cmd([java,"-cp",td,"Main"], capture=capture)
        except OSError as e: spawn_error_generic(e)

def exec_java_file(path,capture=False):
    with TempDirCtx("run-java") as td:
        base=os.path.basename(path); dest=os.path.join(td,base)
        try: shutil.copyfile(path,dest)
        except OSError as e: raise RunError(f"failed to copy Java source from {path} to {dest}\n\nCaused by:\n    {os_error_str(e)}")
        check_friendly("java")
        javac=which("javac"); java=which("java") or "java"
        stem=os.path.splitext(base)[0]
        try: rc,out,err=run_cmd([javac, dest], cwd=td, capture=capture)
        except OSError as e: spawn_error_generic(e)
        if rc!=0: return rc,out,err
        try: return run_cmd([java,"-cp",td,stem], capture=capture)
        except OSError as e: spawn_error_generic(e)

def exec_kotlin_code(code,capture=False):
    check_friendly("kotlin")
