    if has(r'^\s*def\s+\w+\s*\([^)]*\)\s*:', re.M) or has(r'^\s*(if|elif|else|for|while|try|except|finally|with)\b[^\n]*:\s*$', re.M) or "__name__" in s or has(r'\bself\.', s) or has(r'^\s*(import|from)\s+[A-Za-z_][\w\.]*', re.M) or has(r'(f|F)["\'].*\{'):
