def language_from_path(path):
    # extension based, lowercase ext
    m = re.search(r'\.([^./\\]+)$', str(path))
    if not m:
        return None
    return EXT_TO_LANG.get(m.group(1).lower())

def is_file_candidate(path):
    p = str(path)
    if os.path.exists(p):
