# ---------- REPL ----------
PY_SESSION_RUNNER = r'''
import sys, ast, traceback
path = sys.argv[1]
src = open(path, encoding="utf-8").read()
lines = src.splitlines()
markers = set()
for idx, line in enumerate(lines, start=1):
    if line.strip() == "#__repl_expr__":
        markers.add(idx)
try:
    tree = ast.parse(src, filename=path)
except SyntaxError as e:
    sys.stderr.write("".join(traceback.format_exception_only(type(e), e)))
    sys.exit(1)
# transform marked top-level expressions
new_body = []
for node in tree.body:
    if isinstance(node, ast.Expr) and node.end_lineno is not None and (node.end_lineno + 1) in markers:
        call = ast.Call(func=ast.Name(id="print", ctx=ast.Load()), args=[ast.Call(func=ast.Name(id="repr", ctx=ast.Load()), args=[node.value], keywords=[])], keywords=[])
        new_node = ast.Expr(value=call)
        new_body.append(ast.copy_location(new_node, node))
    else:
        new_body.append(node)
tree.body = new_body
ast.fix_missing_locations(tree)
g = {"__name__": "__main__", "__file__": path, "__package__": None, "__builtins__": __builtins__}
sys.argv = [path]
try:
    code = compile(tree, path, "exec")
    exec(code, g)
except SystemExit:
    raise
except BaseException as e:
    tb = e.__traceback__
    if tb is not None and tb.tb_next is not None:
        tb = tb.tb_next
    sys.stderr.write("".join(traceback.format_exception(type(e), e, tb)))
    sys.exit(1)
'''

def normalize_repl_entry(entry):
    e = entry.strip()
    if e.endswith(";"):
        e = e[:-1].rstrip()
    return e

def is_bare_expression(entry, lang):
    e = entry.strip()
    if not e or "\n" in e:
        return False
    if ";" in e:
        return False
    # statements / declarations starting words
    low = e.lower()
    start_words = ("import ", "from ", "def ", "class ", "for ", "while ", "if ", "elif", "else:", "try:", "except", "finally:", "with ", "return", "yield", "raise", "assert", "del ", "global", "pass", "break", "continue", "let ", "my ", "var ", "const ", "func ", "fn ", "fun ", "pub ", "struct ", "enum ", "type ", "package ", "module ", "use ", "sub ", "#", "void ", "int ", "long ", "float ", "double ", "char ", "bool ", "string ", "unsigned ", "static ", "final ")
    for w in start_words:
        if low.startswith(w):
            return False
    if lang == "go" and (e.startswith("fmt.Print") or e.startswith("fmt.Fprint")):
        return False
    if lang == "python":
        if e.startswith("print("):
            return False
        # assignment (single = not ==, >=, <=, !=)
        if re.search(r'(?<![=!<>+\-*/%])=(?![=])', e) and not e.startswith("("):
            # walrus in parens is expression
            if ":=" not in e:
                return False
        # dotted function call like sys.stderr.write(...)
        m = re.match(r'^([A-Za-z_][\w\.]*)\s*\(', e)
        if m and "." in m.group(1):
            return False
        try:
            ast_tree = __import__("ast").parse(e, mode="eval")
        except Exception:
            return False
        return True
    # declarations with a type word (c-like): "type name ..." handled by start words, also std::string
    if re.match(r'^(std::|string\s+|boolean\s+)\w*\s+\w+', e):
        return False
    # simple assignment is an expression in C-like languages, but not a declaration
    # positives
    if re.match(r'^[A-Za-z_]\w*$', e):
        return True
    if re.match(r'^-?\d+(\.\d+)?$', e):
        return True
    if (e.startswith('"') and e.endswith('"')) or (e.startswith("'") and e.endswith("'")):
        return True
    if e.startswith("(") or e.startswith("[") or e.startswith("{"):
        return True
    # call with plain function name, possibly chained after first call
    if re.match(r'^[A-Za-z_]\w*\s*\(', e):
        return True
    # subscript / attribute / member access
    if re.match(r'^[A-Za-z_][\w\.\[\]\(\)]*$', e):
        return True
    # binary / comparison operators
    if re.search(r'\s[-+*/%<>=&|^]\s|\s(==|!=|<=|>=|&&|\|\|)\s', e):
        # assignment handled above; declaration excluded by start words
        if re.search(r'(?<![=!<>])=(?![=])', e) and lang in ("rust","c","cpp","go","perl"):
            return True
        return True
    return False

class Session:
    def __init__(self, lang):
        self.lang = lang
        self.entries = []
        self.prev_out = b""
        self.prev_err = b""
        self.dir = None
    def ensure_dir(self, prefix):
        if self.dir is None:
            self.dir = make_temp_dir(prefix)
        return self.dir
    def reset(self):
        self.entries = []
        self.prev_out = b""
        self.prev_err = b""
        if self.dir:
            import shutil as _sh; _sh.rmtree(self.dir, ignore_errors=True); self.dir=None
    # to be implemented per language below
    def run_current(self):
        raise NotImplementedError

class PythonSession(Session):
    def run_current(self):
        d = self.ensure_dir("run-python-repl")
        path = os.path.join(d, "session.py")
        header = ["# session", "import sys", "# repl"]
        out_lines = list(header)
        for entry in self.entries:
            expr = is_bare_expression(entry, "python")
            out_lines.extend(entry.split("\n"))
            if expr:
                out_lines.append("#__repl_expr__")
        with open(path, "w") as f:
            f.write("\n".join(out_lines)+"\n")
        exe = resolve_python() or "python3"
        try:
            return run_cmd([exe, "-c", PY_SESSION_RUNNER, path], capture=True)
        except OSError as e:
            spawn_error_generic(e)

class BashSession(Session):
    def run_current(self):
        d = self.ensure_dir("run-bash-repl")
        path = os.path.join(d, "session.sh")
        lines = ["#!/bin/bash", "# session"]
        for entry in self.entries:
            lines.extend(entry.split("\n"))
        with open(path, "w") as f: f.write("\n".join(lines)+"\n")
        try:
            return run_cmd([bash_exe(), path], capture=True)
        except OSError as e:
            spawn_error_generic(e)

class PerlSession(Session):
    def run_current(self):
        exe = check_friendly("perl")
        d = self.ensure_dir("run-perl-repl")
        path = os.path.join(d, "session.pl")
        lines = ["use strict;", "use warnings;", "use feature 'say';", "# session"]
        for entry in self.entries:
            if is_bare_expression(entry, "perl"):
                # print arguments first are entry expression (in parens), then newline
                lines.append(f'print(({entry}), "\\n");')
            else:
                lines.append(entry+";")
        with open(path, "w") as f: f.write("\n".join(lines)+"\n")
        try:
            return run_cmd([exe, "session.pl"], cwd=d, capture=True)
        except OSError as e:
            spawn_error_generic(e)

class GenericScriptSession(Session):
    ext_map = {"javascript":"js","ruby":"rb","lua":"lua","php":"php","elixir":"ex","julia":"jl","r":"R","dart":"dart","groovy":"groovy","haskell":"hs","swift":"swift","crystal":"cr","zig":"zig","nim":"nim","typescript":"ts"}
    def run_current(self):
        lang=self.lang
        if lang=="typescript":
            if not which("deno"): raise RunError(deno_missing("inline"))
        elif lang in FRIENDLY:
            check_friendly(lang)
        d = self.ensure_dir(f"run-{lang}-repl")
        ext = self.ext_map.get(lang,"txt")
        path = os.path.join(d, f"session.{ext}")
        lines=[]
        if lang=="php": lines.append("<?php")
        for entry in self.entries: lines.extend(entry.split("\n"))
        with open(path,"w") as f: f.write("\n".join(lines)+"\n")
        if lang=="javascript": cmd=["node", path]
        elif lang=="ruby": cmd=["ruby", path]
        elif lang=="typescript": cmd=[which("deno"),"run",path]
        else:
            exe = which(FRIENDLY[lang][0]) if lang in FRIENDLY else lang
            if lang=="crystal": cmd=[exe,"run",path]
            elif lang=="zig": cmd=[exe,"run",path]
            elif lang=="nim": cmd=[exe,"c","-r","--hints:off",path]
            else: cmd=[exe,path]
        try:
            return run_cmd(cmd, capture=True)
        except OSError as e:
            spawn_error_generic(e)

class GoSession(Session):
    def run_current(self):
        # import/package entries do not trigger a run
        if self.entries and (self.entries[-1].lstrip().startswith("import ") or self.entries[-1].lstrip().startswith("package ")):
            return 0, self.prev_out, self.prev_err
        exe = check_friendly("go")
        d = self.ensure_dir(".tmp")
        # collect imports
        imports=[]
        body=[]
        for entry in self.entries:
            es=entry.strip()
            if es.startswith("import "):
                spec=es[len("import "):].strip()
                # import ( ... ) multi not handled
                imports.append(spec); continue
            if es.startswith("package "): continue
            if is_bare_expression(entry,"go"):
                body.append(f"\tfmt.Println({entry})")
            else:
                for ln in entry.split("\n"): body.append("\t"+ln)
        lines=[]
        lines.append("package main")
        lines.append("")
        lines.append("import (")
        lines.append('\t"fmt"')
        for imp in imports:
            if imp not in ('"fmt"',): lines.append("\t"+imp)
        lines.append(")")
        # filler lines to place first body statement at line 16 (+ number of extra imports)
        while len(lines) < 14:
            lines.append("")
        lines.append("func main() {")
        lines.extend(body)
        lines.append("}")
        path=os.path.join(d,"main.go")
        with open(path,"w") as f: f.write("\n".join(lines)+"\n")
        try:
            return run_cmd([exe,"run","main.go"], cwd=d, capture=True)
        except OSError as e:
            spawn_error_generic(e)

class RustSession(Session):
    def run_current(self):
        exe = check_friendly("rust")
        d = self.ensure_dir(".tmp")
        tops=[]; body=[]
        for entry in self.entries:
            es=entry.strip()
            if es.startswith("fn main"):
                # extract inside braces as statements
                m=re.search(r'\{(.*)\}\s*$', es, re.S)
                if m:
                    inner=m.group(1).strip()
                    if inner:
                        for stmt in inner.split(";"):
                            st=stmt.strip()
                            if st: body.append(("raw", st))
                    continue
            if es.startswith("fn ") or es.startswith("use ") or es.startswith("struct ") or es.startswith("impl "):
                tops.append(entry); continue
            if is_bare_expression(entry,"rust"):
                body.append(("expr",entry))
            else:
                body.append(("raw",entry))
        lines=[]
        lines.append("#[allow(dead_code)]")
        lines.append("fn __print<T: std::fmt::Debug>(value: T) {")
        lines.append('    println!("{:?}", value);')
        lines.append("}")
        lines.append("")
        lines.append("")
        lines.append("")
        # tops shift main down (original counts unknown); keep tops before main
        lines.extend(tops)
        lines.append("fn main() {")
        for kind,entry in body:
            if kind=="expr": lines.append(f"    __print({entry});")
            else:
                for ln in entry.split("\n"): lines.append("    "+ln)
        lines.append("}")
        path=os.path.join(d,"session.rs")
        with open(path,"w") as f: f.write("\n".join(lines)+"\n")
        binary=os.path.join(d,"run_rust_binary")
        try:
            rc,out,err=run_cmd([exe, path, "-o", binary, "--crate-name","run_snippet","--edition","2021"], capture=True)
        except OSError as e: spawn_error_generic(e)
        if rc!=0: return rc,out,err
        try: return run_cmd([binary], capture=True)
        except OSError as e: spawn_error_generic(e)

class CSession(Session):
    def run_current(self):
        comp=find_c_compiler()
        if not comp: raise RunError("C support requires a C compiler such as `cc`, `clang`, or `gcc`. Install one and ensure it is on your PATH.")
        d=self.ensure_dir(".tmp")
        body=[]; includes=[]
        for entry in self.entries:
            es=entry.strip()
            if es.startswith("#include"):
                # includes may be part of a multiline entry; first line is include rest body
                parts=entry.split("\n"); includes.append(parts[0]);
                if len(parts)>1:
                    rest="\n".join(parts[1:])
                    # if rest is a main function, extract?
                    body.append(("raw",rest))
                continue
            if is_bare_expression(entry,"c"): body.append(("expr",entry))
            else: body.append(("raw",entry))
        lines=[]
        lines.append("#include <stdio.h>")
        lines.append("#include <stdlib.h>")
        lines.append("#include <string.h>")
        lines.append('static void __print_int(long long v) { printf("%lld\\n", v); }')
        lines.append('static void __print_uint(unsigned long long v) { printf("%llu\\n", v); }')
