def make_session(lang):
    if lang=="python": return PythonSession(lang)
    if lang=="bash": return BashSession(lang)
    if lang=="perl": return PerlSession(lang)
    if lang=="go": return GoSession(lang)
    if lang=="rust": return RustSession(lang)
    if lang=="c": return CSession(lang)
    if lang=="cpp": return CppSession(lang)
    if lang in ("java","kotlin","csharp"): return CompiledSession(lang)
    return GenericScriptSession(lang)

def bracket_quote_incomplete(lines, lang):
    text="\n".join(lines)
    # quote and bracket scan (ignore escaped chars inside quotes)
    stack=[]
    i=0; state=None; triple=False
    pairs={')':'(',']':'[','}':'{'}
    while i < len(text):
        ch=text[i]
        if state:
            if ch=="\\":
                i+=2; continue
            if triple:
                if text[i:i+3]==state*3:
                    state=None; triple=False; i+=3; continue
                i+=1; continue
            else:
                if ch==state:
                    state=None
                i+=1; continue
        else:
            if ch in ('"',"'"):
                if text[i:i+3]==ch*3:
                    state=ch; triple=True; i+=3; continue
                state=ch; i+=1; continue
            if ch in "([{":
                stack.append(ch)
            elif ch in ")]}":
                if stack and stack[-1]==pairs[ch]: stack.pop()
                else:
                    # mismatched closing: treat as complete (error will surface)
                    pass
            i+=1
    if state: return True
    if stack: return True
    last=lines[-1].strip() if lines else ""
    if last.endswith("\\"): return True
    if last.endswith(":"): return True
    # a block introduced by a colon continues until a blank line
    if len(lines)>1 and any(l.rstrip().endswith(":") for l in lines[:-0]):
        # if any earlier line ends with colon, stay in block mode
        if any(l.rstrip().endswith(":") for l in lines):
            return True
    if lang in ("c","cpp") and text.lstrip().startswith("#include") and "}" not in text:
        return True
    return False

REPL_HELP = """Commands:
  :help                 Show this help message
  :languages            List available languages
  :lang <id>            Switch to language <id>
  :detect on|off        Enable or disable auto language detection
  :reset                Reset the current language session
  :load <path>          Execute a file in the current language
  :exit, :quit          Leave the REPL
Any language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php."""

def run_repl(initial_lang, detect_enabled=True):
    # history handling
    import atexit
    try:
        import readline
    except Exception:
        readline=None
    home = os.path.expanduser("~")
    hist_path = os.path.join(home, ".run_history") if home else None
    history_entries=[]
    if hist_path and os.path.exists(hist_path):
        try:
            with open(hist_path, encoding="utf-8", errors="ignore") as f:
                raw_lines=f.read().splitlines()
            if raw_lines and raw_lines[0]=="#V2": raw_lines=raw_lines[1:]
            for ln in raw_lines:
                # decode rustyline escapes
                out=""; idx=0
                while idx < len(ln):
                    if ln[idx]=="\\" and idx+1 < len(ln):
                        nxt=ln[idx+1]
                        if nxt=="n": out+="\n"; idx+=2; continue
                        if nxt=="\\": out+="\\"; idx+=2; continue
                    out+=ln[idx]; idx+=1
                history_entries.append(out)
                if readline:
                    try: readline.add_history(out)
                    except Exception: pass
        except Exception:
            pass
    def save_history():
        if not hist_path: return
        try:
            with open(hist_path,"w",encoding="utf-8") as f:
                f.write("#V2\n")
                for ent in history_entries:
                    enc=ent.replace("\\","\\\\").replace("\n","\\n")
                    f.write(enc+"\n")
        except Exception:
            pass
    sys.stdout.write("run universal REPL. Type :help for commands.\n"); sys.stdout.flush()
    current=initial_lang
    detect_on=detect_enabled
    sessions={}
    def get_session(lang):
        if lang not in sessions: sessions[lang]=make_session(lang)
        return sessions[lang]
    buffer=[]
    # main loop
    while True:
        prompt = "... " if buffer else f"{current}>>> "
        try:
            if readline is not None:
                line = input(prompt)
            else:
                sys.stdout.write(prompt); sys.stdout.flush()
                line = sys.stdin.readline()
                if line=="": raise EOFError
                line=line.rstrip("\n")
        except EOFError:
            sys.stdout.write("\nbye\n"); sys.stdout.flush()
            save_history()
            return 0
        except KeyboardInterrupt:
            sys.stdout.write("^C\n"); sys.stdout.flush()
            buffer=[]
            continue
        # continuation handling
        if buffer:
            if line.strip()=="":
                entry_text="\n".join(buffer); buffer=[]
                # fall through to execution below with entry_text
            else:
                buffer.append(line)
                if bracket_quote_incomplete(buffer, current):
                    continue
                entry_text="\n".join(buffer); buffer=[]
                # fall through
        else:
            if line.strip()=="":
                continue
            trimmed=line.strip()
            if trimmed.startswith(":"):
                # command; add to history
                history_entries.append(line.strip())
                if readline:
                    try: readline.add_history(line.strip())
                    except Exception: pass
                content=trimmed[1:]
                parts=content.split()
                if not parts:
                    continue
                cmd=parts[0]
                if cmd in ("exit","quit"):
                    save_history(); return 0
                elif cmd=="help":
                    sys.stdout.write(REPL_HELP+"\n")
                elif cmd=="languages":
                    sys.stdout.write(f"available languages: {LANG_CSV}\n")
                elif cmd=="lang":
                    if len(parts)<2:
                        sys.stdout.write("usage: :lang <language>\n")
                    else:
                        parsed=parse_language(parts[1])
                        if parsed is None:
                            raise RunError(f"language '{parts[1].strip().lower()}' not supported. Available: {LANG_CSV}")
                        if parsed==current: sys.stdout.write(f"already using {current}\n")
                        else: current=parsed; sys.stdout.write(f"switched to {current}\n")
                elif cmd=="detect":
                    if len(parts)<2:
                        sys.stdout.write("auto-detect is enabled\n" if detect_on else "auto-detect is disabled\n")
                    elif parts[1]=="on": detect_on=True; sys.stdout.write("auto-detect enabled\n")
                    elif parts[1]=="off": detect_on=False; sys.stdout.write("auto-detect disabled\n")
                    elif parts[1]=="toggle":
                        detect_on=not detect_on; sys.stdout.write("auto-detect enabled\n" if detect_on else "auto-detect disabled\n")
                    else: sys.stdout.write("usage: :detect <on|off|toggle>\n")
                elif cmd=="reset":
                    get_session(current).reset(); sys.stdout.write(f"session for '{current}' reset\n")
                elif cmd=="load":
                    if len(parts)<2: sys.stdout.write("usage: :load <path>\n")
                    else:
                        path=parts[1]
                        start=time.time()
                        rc,out,err = execute_file(current, path, capture=True)
                        elapsed=int((time.time()-start)*1000)
                        if out: sys.stdout.buffer.write(out); sys.stdout.flush()
                        if err: sys.stderr.buffer.write(err); sys.stderr.flush()
                        if rc!=0: sys.stdout.write(f"[exit code {rc}] ({elapsed}ms)\n")
                else:
                    parsed=parse_language(cmd)
                    if parsed is not None:
                        if parsed==current: sys.stdout.write(f"already using {current}\n")
                        else: current=parsed; sys.stdout.write(f"switched to {current}\n")
                    else:
                        sys.stdout.write(f"unknown command: :{cmd}. Type :help for help.\n")
                sys.stdout.flush(); continue
            # ordinary line
            if bracket_quote_incomplete([line], current):
                buffer=[line]; continue
            entry_text=line
        # execute code entry
        entry = normalize_repl_entry(entry_text)
        if entry=="":
            continue
        history_entries.append(entry)
        if readline:
            try: readline.add_history(entry)
            except Exception: pass
        if detect_on:
            detected=detect_language(entry)
            if detected is not None and detected!=current:
                sys.stdout.write(f"[auto-detect] switching {current} \u2192 {detected}\n"); sys.stdout.flush()
                current=detected
        session=get_session(current)
        session.entries.append(entry)
        start=time.time()
        try:
            rc,out,err = session.run_current()
        except RunError:
            session.entries.pop(); raise
        except Exception:
            session.entries.pop(); raise
        elapsed=int((time.time()-start)*1000)
        # delta outputs
        if out.startswith(session.prev_out): dout=out[len(session.prev_out):]
        else: dout=out
        if err.startswith(session.prev_err): derr=err[len(session.prev_err):]
        else: derr=err
        if dout: sys.stdout.buffer.write(dout)
        sys.stdout.flush()
        if derr: sys.stderr.buffer.write(derr)
        sys.stderr.flush()
        if rc!=0:
            session.entries.pop()
            sys.stdout.write(f"[exit code {rc}] ({elapsed}ms)\n"); sys.stdout.flush()
        else:
            session.prev_out=out; session.prev_err=err

PYEOF
echo ok"}

